"""# CNN-LSTM maize yield prediction on 20 Multi-Modal bands (Colab)

District-level maize yield (t/ha) for Zambia from multi-modal satellite cropland patches.

* **Bands:** 20 bands total -- 12 Sentinel-2 L2A bands (B1, B2, B3, B4, B5, B6, B7, B8, B8A, B9, B11, B12), 2 Vegetation Indices (NDVI, EVI), 3 Climate variables (CHIRPS precip, ERA5 temp max/min), and 3 Sentinel-1 SAR metrics (VV, VH, VV/VH ratio). Resampled to 20 m.
* **Ground truth:** your CFS district yields, `data/real_yields.csv`.
* **Time axis:** 8 two-week windows, Nov -> Feb, per growing season (Early Prediction limit).
* **Model:** Attention-Augmented CNN-LSTM with Coordinate Fusion.
* **Evaluation:** district-held-out 5-fold CV and leave-one-season-out CV, scored per
  district-season (never per patch), against simple baselines.
* **Output:** predicted yield for every district and season, saved to Google Drive.

Pre-registered interpretation rules:
`docs/phase4_model_development/v29_cnn_lstm_all_s2_bands_colab.md`.
This notebook is generated by `scripts/generate_colab_v29_cnn_lstm.py`; edit that, not this file.

## How to run

1. **Runtime -> Change runtime type -> GPU (T4).**
2. Upload `real_yields.csv` to `MyDrive/MaizeYieldPrediction/data/` (or change `YIELDS_CSV`).
3. Set `EE_PROJECT` below to your Earth Engine cloud project.
4. **Runtime -> Run all.** Sign in to Google Drive and Earth Engine when asked.

Patch extraction is cached on Drive, so a disconnected session resumes where it stopped.
Set `DRY_RUN = True` first to test the whole pipeline on synthetic data in ~2 minutes.

## 1. Configuration
"""

