            cell, diag = train_eval(np.arange(len(X)), np.arange(len(Xp)),
                                    os.path.join(RESULTS_DIR, 'final'), Xsrc=Xp, msrc=mp)
            vf = mp.groupby('cell').valid_frac.mean().rename('valid_frac')
            cell = cell.merge(vf, left_on='cell', right_index=True)
            if 'gb_to_proj' in globals():
                cell['project_district'] = cell.gb_district.map(gb_to_proj).fillna('')
            else:
                cell['project_district'] = ''
            if not cell_obs.empty:
                cell = cell.merge(cell_obs[['cell', 'obs']], on='cell', how='left')
            else:
                cell['obs'] = np.nan
            cell['in_training'] = cell.obs.notna().astype(int)
            out = cell.rename(columns={'gb_district': 'district', 'pred': 'pred_yield_t_ha',
                                       'obs': 'observed_yield_t_ha'})[
                ['district', 'project_district', 'season', 'pred_yield_t_ha', 'pred_raw',
                 'observed_yield_t_ha', 'in_training', 'valid_frac']].sort_values(['district', 'season'])
            path = os.path.join(RESULTS_DIR, 'predictions_all_districts.csv')
