# 2. Example: Plotting a synthetic patch band & writing with rasterio
def visualize_and_save_patch(patch_idx=0, band_idx=7, filename='sample_patch.tif'):
    """
    Plots a single patch's band (default: B8 NIR) using matplotlib
    and saves it to disk as a GeoTIFF using rasterio.
    """
    if 'X' in globals() and len(X) > patch_idx:
        # Extract patch [T, PATCH, PATCH, BANDS]
        # Let's take the median across all time windows (T=12) for visualization
        patch_data = X[patch_idx].astype(np.float32)
        band_data = np.median(patch_data[:, :, :, band_idx], axis=0)

        # Plot using matplotlib
        plt.figure(figsize=(5, 5))
        plt.imshow(band_data, cmap='YlGnBu')
        plt.colorbar(label='Reflectance')

        band_name = BANDS[band_idx] if 'BANDS' in globals() and len(BANDS) > band_idx else f'Band {band_idx}'
        plt.title(f'Patch {patch_idx} - {band_name} (Median over season)')
        plt.axis('off')
        plt.show()

        # Save using rasterio
        transform = from_origin(28.0, -15.0, 20, 20)  # Dummy geospatial transform coords
        with rasterio.open(
            filename,
            'w',
            driver='GTiff',
            height=band_data.shape[0],
            width=band_data.shape[1],
            count=1,
            dtype=band_data.dtype,
            crs='EPSG:32735',
            transform=transform,
        ) as dst:
            dst.write(band_data, 1)
        print(f'Successfully saved patch band as geoTIFF to: {filename}')
    else:
        print('No patch data array (X) found in kernel state.')

# Run the helper on the first patch (using B8/NIR band)
visualize_and_save_patch(patch_idx=0, band_idx=7)

