import pandas as pd
import numpy as np
import matplotlib.pyplot as plt
import seaborn as sns
from sklearn.metrics import r2_score, mean_squared_error, mean_absolute_error

if 'out' in globals() and isinstance(out, pd.DataFrame) and not out.empty:
    # Filter data with both observed and predicted yields
    eval_df = out.dropna(subset=['observed_yield_t_ha', 'pred_yield_t_ha']).copy()

    season_metrics = []
    # Group by season and compute metrics
    for season, group in eval_df.groupby('season'):
        obs = group['observed_yield_t_ha'].to_numpy()
        pred = group['pred_yield_t_ha'].to_numpy()

        r2 = r2_score(obs, pred) if len(obs) > 1 else np.nan
        rmse = np.sqrt(mean_squared_error(obs, pred))
        mae = mean_absolute_error(obs, pred)

        season_metrics.append({
            'Season': str(int(season)),
            'R2 Score': r2,
            'RMSE (t/ha)': rmse,
            'MAE (t/ha)': mae
        })

    metrics_df = pd.DataFrame(season_metrics)

    # Plotting
    sns.set_theme(style='whitegrid')
    fig, axes = plt.subplots(1, 3, figsize=(18, 5))

    # R2 plot
    sns.barplot(x='Season', y='R2 Score', data=metrics_df, ax=axes[0], palette='crest', hue='Season', legend=False)
    axes[0].set_title('R² Score by Season (Higher is Better)', fontsize=12, fontweight='bold')
    axes[0].set_ylabel('R² Score')
    axes[0].set_ylim(0, 1.1)
    for container in axes[0].containers:
        axes[0].bar_label(container, fmt='%.3f', padding=3, fontweight='bold')

    # RMSE plot
    sns.barplot(x='Season', y='RMSE (t/ha)', data=metrics_df, ax=axes[1], palette='flare', hue='Season', legend=False)
    axes[1].set_title('RMSE by Season (Lower is Better)', fontsize=12, fontweight='bold')
    axes[1].set_ylabel('RMSE (t/ha)')
    axes[1].set_ylim(0, max(metrics_df['RMSE (t/ha)']) * 1.25)
    for container in axes[1].containers:
        axes[1].bar_label(container, fmt='%.3f', padding=3, fontweight='bold')

    # MAE plot
    sns.barplot(x='Season', y='MAE (t/ha)', data=metrics_df, ax=axes[2], palette='magma', hue='Season', legend=False)
    axes[2].set_title('MAE by Season (Lower is Better)', fontsize=12, fontweight='bold')
    axes[2].set_ylabel('MAE (t/ha)')
    axes[2].set_ylim(0, max(metrics_df['MAE (t/ha)']) * 1.25)
    for container in axes[2].containers:
        axes[2].bar_label(container, fmt='%.3f', padding=3, fontweight='bold')

    plt.suptitle('Crop Yield Model Validation Metrics Grouped by Growing Season', fontsize=15, fontweight='bold', y=1.05)
    plt.tight_layout()
    plt.show()
else:
    print("Prediction dataset 'out' is not loaded or is empty.")

