    eval_df = out.dropna(subset=['observed_yield_t_ha', 'pred_yield_t_ha']).copy()

    seasons = sorted(eval_df['season'].unique())
    n_seasons = len(seasons)

    # Set up a grid of subplots dynamically
    cols = 3
    rows = int(np.ceil(n_seasons / cols))
    fig, axes = plt.subplots(rows, cols, figsize=(15, 5 * rows), sharex=True, sharey=True)
    axes = axes.flatten()

    for i, season in enumerate(seasons):
        ax = axes[i]
        season_df = eval_df[eval_df['season'] == season]

        obs = season_df['observed_yield_t_ha'].to_numpy()
        pred = season_df['pred_yield_t_ha'].to_numpy()

        # Scatter plot for current season
        ax.scatter(obs, pred, alpha=0.7, color='forestgreen', edgecolors='k', s=40)
        ax.plot([0.5, 4.0], [0.5, 4.0], 'r--', alpha=0.8)

        # Compute individual season metrics for titles
        from sklearn.metrics import r2_score, mean_squared_error
        r2 = r2_score(obs, pred) if len(obs) > 1 else np.nan
        rmse = np.sqrt(mean_squared_error(obs, pred))

        ax.set_title(f"Season {int(season)}\n$R^2$: {r2:.3f} | RMSE: {rmse:.3f}", fontsize=11)
        ax.set_xlim(0.4, 4.1)
        ax.set_ylim(0.4, 4.1)
        ax.grid(True, linestyle=':', alpha=0.6)

        if i % cols == 0:
            ax.set_ylabel('Predicted Yield (t/ha)')
        if i >= (rows - 1) * cols or rows == 1:
            ax.set_xlabel('Observed Yield (t/ha)')

    # Hide any unused axes in the grid
    for j in range(i + 1, len(axes)):
        fig.delaxes(axes[j])

    plt.suptitle('Maize Yields by Growing Season: Observed vs Predicted (v29)', fontsize=14, y=1.02)
    plt.tight_layout()
    plt.show()
