import matplotlib.pyplot as plt
import numpy as np

if 'out' in globals() and not out.empty:
    # Filter data containing both observed and predicted yields
    eval_df = out.dropna(subset=['observed_yield_t_ha', 'pred_yield_t_ha']).copy()
    eval_df['residual'] = eval_df['observed_yield_t_ha'] - eval_df['pred_yield_t_ha']

    seasons = sorted(eval_df['season'].unique())
    n_seasons = len(seasons)

    # Plot residuals vs predicted yields dynamically for each season
    cols = 3
    rows = int(np.ceil(n_seasons / cols))
    fig, axes = plt.subplots(rows, cols, figsize=(15, 5 * rows), sharex=True, sharey=True)
    axes = axes.flatten()

    for i, season in enumerate(seasons):
        ax = axes[i]
        season_df = eval_df[eval_df['season'] == season]

        pred = season_df['pred_yield_t_ha'].to_numpy()
        res = season_df['residual'].to_numpy()

        # Scatter predicted vs Residual
        ax.scatter(pred, res, alpha=0.7, color='purple', edgecolors='k', s=40)
        ax.axhline(0, color='black', linestyle='--', alpha=0.8)

        # Add a local trendline to visualize bias pattern
        if len(pred) > 1:
            z = np.polyfit(pred, res, 1)
            p = np.poly1d(z)
            xp = np.linspace(pred.min(), pred.max(), 100)
            ax.plot(xp, p(xp), 'r-', alpha=0.6, label='Trend')

        ax.set_title(f"Season {int(season)}", fontsize=11)
        ax.set_xlim(0.4, 4.1)
        ax.set_ylim(-1.5, 1.5)
        ax.grid(True, linestyle=':', alpha=0.6)

        if i % cols == 0:
            ax.set_ylabel('Residual (Observed - Predicted)')
        if i >= (rows - 1) * cols or rows == 1:
            ax.set_xlabel('Predicted Yield (t/ha)')

    # Hide any unused axes in the grid
    for j in range(i + 1, len(axes)):
        fig.delaxes(axes[j])

    plt.suptitle('Prediction Residuals vs. Predicted Yields by Season', fontsize=14, y=1.02)
    plt.tight_layout()
    plt.show()
