import pandas as pd
import numpy as np
import matplotlib.pyplot as plt
import seaborn as sns

# Dynamic Recovery: Reconstruct 'district_perf_sorted' if missing
if 'out' in globals() and isinstance(out, pd.DataFrame) and not out.empty:
    eval_df = out.dropna(subset=['observed_yield_t_ha', 'pred_yield_t_ha']).copy()
    eval_df['residual'] = eval_df['observed_yield_t_ha'] - eval_df['pred_yield_t_ha']
    eval_df['abs_residual'] = eval_df['residual'].abs()

    district_perf = eval_df.groupby('district').agg(
        mean_observed_yield=('observed_yield_t_ha', 'mean'),
        mean_predicted_yield=('pred_yield_t_ha', 'mean'),
        mean_absolute_error=('abs_residual', 'mean')
    ).reset_index()

    district_perf_sorted = district_perf.sort_values(by='mean_absolute_error').reset_index(drop=True)
    globals()['district_perf_sorted'] = district_perf_sorted
else:
    district_perf_sorted = None

if district_perf_sorted is not None and not district_perf_sorted.empty:
    best_10 = district_perf_sorted.head(10).copy()
    worst_10 = district_perf_sorted.tail(10).copy()

    # Combine them for plotting side-by-side
    best_10['Group'] = 'Best Performing (Lowest MAE)'
    worst_10['Group'] = 'Worst Performing (Highest MAE)'
    plot_df = pd.concat([best_10, worst_10])

    fig, axes = plt.subplots(1, 2, figsize=(15, 6), sharex=True)

    # Left Plot: Best
    sns.barplot(
        x='mean_absolute_error',
        y='district',
        data=best_10,
        ax=axes[0],
        palette='crest',
        hue='district',
        legend=False
    )
    axes[0].set_title('Top 10 Best Performing Districts (Lowest MAE)')
    axes[0].set_xlabel('Mean Absolute Error (t/ha)')
    axes[0].set_ylabel('District')
    axes[0].grid(True, linestyle=':', alpha=0.6)

    # Right Plot: Worst
    sns.barplot(
        x='mean_absolute_error',
        y='district',
        data=worst_10.sort_values(by='mean_absolute_error', ascending=False),
        ax=axes[1],
        palette='flare',
        hue='district',
        legend=False
    )
    axes[1].set_title('Top 10 Worst Performing Districts (Highest MAE)')
    axes[1].set_xlabel('Mean Absolute Error (t/ha)')
    axes[1].set_ylabel('')
    axes[1].grid(True, linestyle=':', alpha=0.6)

    plt.suptitle('Spatial Model Performance comparison (MAE t/ha)', fontsize=16, y=1.02)
    plt.tight_layout()
    plt.show()
