import matplotlib.pyplot as plt
import numpy as np
import pandas as pd

if 'district_perf' in globals() and 'centres' in globals():
    # Calculate a representative lat/lon for each district from centers
    coords = []
    for dist, pts in centres.items():
        if len(pts) > 0:
            pts_arr = np.array(pts)
            # centres are stored as [lon, lat]
            mean_lon = pts_arr[:, 0].mean()
            mean_lat = pts_arr[:, 1].mean()
            coords.append({'district': dist, 'longitude': mean_lon, 'latitude': mean_lat})

    coords_df = pd.DataFrame(coords)

    # Merge coordinates with the performance metrics
    map_df = pd.merge(district_perf, coords_df, on='district', how='inner')

    plt.figure(figsize=(10, 8))
    sc = plt.scatter(
        map_df['longitude'],
        map_df['latitude'],
        c=map_df['mean_absolute_error'],
        cmap='YlOrRd',
        s=150,
        edgecolors='k',
        alpha=0.85
    )

    # Annotate district names for top and bottom performers
    for idx, row in map_df.iterrows():
        if row['mean_absolute_error'] < 0.1 or row['mean_absolute_error'] > 0.42:
            plt.annotate(
                row['district'],
                (row['longitude'], row['latitude']),
                textcoords="offset points",
                xytext=(0, 8),
                ha='center',
                fontsize=8,
                bbox=dict(boxstyle="round,pad=0.1", fc="yellow", alpha=0.5, ec="gray", lw=0.5)
            )

    plt.colorbar(sc, label='Mean Absolute Error (t/ha)')
    plt.title('Spatial Distribution of Maize Yield Prediction Error (MAE) by District', fontsize=14)
    plt.xlabel('Longitude')
    plt.ylabel('Latitude')
    plt.grid(True, linestyle=':', alpha=0.5)
    plt.tight_layout()
    plt.show()
else:
    print("District performance data or coordinate centers are not loaded.")

import pandas as pd
import numpy as np
import matplotlib.pyplot as plt
import seaborn as sns
from scipy.stats import pearsonr, spearmanr

if 'district_perf' in globals() and not district_perf.empty:
    # Extract variables
    obs_mean = district_perf['mean_observed_yield'].to_numpy()
    mae = district_perf['mean_absolute_error'].to_numpy()

    # Calculate Pearson and Spearman correlations
    p_corr, p_val = pearsonr(obs_mean, mae)
    s_corr, s_val = spearmanr(obs_mean, mae)

    print(f"Pearson Correlation: r = {p_corr:.4f} (p-value = {p_val:.4e})")
    print(f"Spearman Rank Correlation: rho = {s_corr:.4f} (p-value = {s_val:.4e})")

    # Plot scatter plot
    plt.figure(figsize=(8, 6))
    sns.regplot(
        x='mean_observed_yield',
        y='mean_absolute_error',
        data=district_perf,
        color='darkcyan',
        scatter_kws={'alpha': 0.7, 'edgecolors': 'k', 's': 70},
        line_kws={'color': 'red', 'linestyle': '--', 'linewidth': 1.5}
    )

    # Annotate coefficients on the plot
    plt.text(
        0.05, 0.95,
        f"Pearson r: {p_corr:.3f}\nSpearman \u03c1: {s_corr:.3f}",
        transform=plt.gca().transAxes,
        fontsize=11,
        verticalalignment='top',
        bbox=dict(boxstyle='round,pad=0.5', facecolor='white', alpha=0.8, edgecolor='gray')
    )

    plt.title('Correlation Between District Mean Observed Yield and MAE', fontsize=13)
    plt.xlabel('Mean Observed Maize Yield (t/ha)', fontsize=11)
    plt.ylabel('Mean Absolute Error (t/ha)', fontsize=11)
    plt.grid(True, linestyle=':', alpha=0.6)
    plt.tight_layout()
    plt.show()
