import pandas as pd
import numpy as np
import matplotlib.pyplot as plt
import seaborn as sns
from sklearn.metrics import r2_score, mean_squared_error, mean_absolute_error

if 'out' in globals() and not out.empty:
    # Filter data with both observed and predicted yields
    eval_df = out.dropna(subset=['observed_yield_t_ha', 'pred_yield_t_ha']).copy()
    eval_df['residual'] = eval_df['observed_yield_t_ha'] - eval_df['pred_yield_t_ha']
    eval_df['abs_residual'] = eval_df['residual'].abs()

    # Calculate metrics for each season
    season_comparison = []
    for season, group in eval_df.groupby('season'):
        obs = group['observed_yield_t_ha'].to_numpy()
        pred = group['pred_yield_t_ha'].to_numpy()

        r2 = r2_score(obs, pred) if len(obs) > 1 else np.nan
        rmse = np.sqrt(mean_squared_error(obs, pred))
        mae = mean_absolute_error(obs, pred)

        season_comparison.append({
            'Season': int(season),
            'Count': len(group),
            'R2 Score': r2,
            'RMSE (t/ha)': rmse,
            'MAE (t/ha)': mae,
            'Is 2022': '2022 Season' if season == 2022 else 'Other Seasons'
        })

    comp_metrics_df = pd.DataFrame(season_comparison)

    print("=== Performance Metrics by Season ===")
    display(comp_metrics_df.round(4))

    # Generate comparative plots
    fig, axes = plt.subplots(1, 3, figsize=(18, 5))

    # R2 Comparison
    sns.barplot(x='Season', y='R2 Score', hue='Is 2022', data=comp_metrics_df, ax=axes[0], dodge=False, palette='Set2')
    axes[0].set_title('R2 Score by Season (Higher is Better)')
    axes[0].set_ylim(0.8, 0.95)
    axes[0].grid(True, linestyle=':', alpha=0.6)

    # RMSE Comparison
    sns.barplot(x='Season', y='RMSE (t/ha)', hue='Is 2022', data=comp_metrics_df, ax=axes[1], dodge=False, palette='Set2')
    axes[1].set_title('RMSE by Season (Lower is Better)')
    axes[1].grid(True, linestyle=':', alpha=0.6)

    # MAE Comparison
    sns.barplot(x='Season', y='MAE (t/ha)', hue='Is 2022', data=comp_metrics_df, ax=axes[2], dodge=False, palette='Set2')
    axes[2].set_title('MAE by Season (Lower is Better)')
    axes[2].grid(True, linestyle=':', alpha=0.6)

    plt.suptitle('Model Performance Comparison: 2022 vs Other Seasons', fontsize=14, y=1.02)
    plt.tight_layout()
    plt.show()
