if 'out' in globals() and not out.empty:
    # Filter to evaluations where we have actual observed yields
    eval_df = out.dropna(subset=['observed_yield_t_ha', 'pred_yield_t_ha']).copy()

    # Calculate absolute error and percentage relative error per record
    eval_df['abs_residual'] = (eval_df['observed_yield_t_ha'] - eval_df['pred_yield_t_ha']).abs()
    eval_df['relative_error_pct'] = (eval_df['abs_residual'] / eval_df['observed_yield_t_ha']) * 100

    # Aggregate by district
    district_relative_perf = eval_df.groupby('district').agg(
        seasons_evaluated=('season', 'count'),
        mean_observed_yield=('observed_yield_t_ha', 'mean'),
        mean_predicted_yield=('pred_yield_t_ha', 'mean'),
        mean_absolute_error=('abs_residual', 'mean'),
        mape_pct=('relative_error_pct', 'mean')
    ).reset_index()

    # Sort by lowest relative error (MAPE)
    district_relative_perf_sorted = district_relative_perf.sort_values(by='mape_pct').reset_index(drop=True)

    print("=== Top 10 Districts with Lowest Relative Error % (MAPE) ===")
    display(district_relative_perf_sorted.head(10).round(4))

    print("\n=== Bottom 10 Districts with Highest Relative Error % (MAPE) ===")
    display(district_relative_perf_sorted.tail(10).round(4))
else:
    print("Prediction dataset 'out' is not loaded in the kernel state.")

import matplotlib.pyplot as plt
import seaborn as sns
import numpy as np
import pandas as pd

if 'out' in globals() and not out.empty:
    # Filter to evaluations where we have actual observed yields
    eval_df = out.dropna(subset=['observed_yield_t_ha', 'pred_yield_t_ha']).copy()
    eval_df['residual'] = eval_df['observed_yield_t_ha'] - eval_df['pred_yield_t_ha']

    # Get top and bottom 10 districts sorted by MAPE
    top_10_districts = list(district_relative_perf_sorted.head(10)['district'])
    bottom_10_districts = list(district_relative_perf_sorted.tail(10)['district'])

    # Slice dataset for top and bottom performers
    top_subset = eval_df[eval_df['district'].isin(top_10_districts)].copy()
    top_subset['group'] = 'Top 10 (Lowest MAPE)'

    bottom_subset = eval_df[eval_df['district'].isin(bottom_10_districts)].copy()
    bottom_subset['group'] = 'Bottom 10 (Highest MAPE)'

    combined_subset = pd.concat([top_subset, bottom_subset])

    # 1. Print metrics
    print("=== Residual Bias: Top 10 Performance Districts ===")
    top_summary = top_subset.groupby('district')['residual'].agg(['count', 'mean', 'std', 'min', 'max'])
    display(top_summary.round(4))

    print("\n=== Residual Bias: Bottom 10 Performance Districts ===")
    bottom_summary = bottom_subset.groupby('district')['residual'].agg(['count', 'mean', 'std', 'min', 'max'])
    display(bottom_summary.round(4))

    # 2. Visualize Distributions
    plt.figure(figsize=(14, 6))

    plt.subplot(1, 2, 1)
    sns.boxplot(
        x='residual',
        y='district',
        data=top_subset,
        palette='crest',
        hue='district',
        legend=False
    )
    plt.axvline(0, color='red', linestyle='--')
    plt.title('Residuals of Top 10 Districts (Lowest MAPE)')
    plt.xlabel('Residual (Observed - Predicted Yield in t/ha)')
    plt.ylabel('District')
    plt.grid(True, linestyle=':', alpha=0.6)

    plt.subplot(1, 2, 2)
    sns.boxplot(
        x='residual',
        y='district',
        data=bottom_subset,
        palette='flare',
        hue='district',
        legend=False
    )
    plt.axvline(0, color='red', linestyle='--')
