    eval_df['abs_residual'] = eval_df['residual'].abs()
    eval_df['relative_error_pct'] = (eval_df['abs_residual'] / eval_df['observed_yield_t_ha']) * 100

    # First determine how many seasons each district has
    district_seasons = eval_df.groupby('district')['season'].nunique().reset_index(name='season_count')
    eval_df = eval_df.merge(district_seasons, on='district')

    # Group districts into Single-season vs Multi-season categories
    eval_df['Group'] = np.where(eval_df['season_count'] == 1, 'Single-season Districts (1 Season)', 'Multi-season Districts (>1 Season)')

    # Calculate aggregate performance metrics for both groups
    comparison_summary = eval_df.groupby('Group').agg(
        total_districts=('district', 'nunique'),
        total_evaluations=('season', 'count'),
        mean_observed_yield=('observed_yield_t_ha', 'mean'),
        mean_predicted_yield=('pred_yield_t_ha', 'mean'),
        mae=('abs_residual', 'mean'),
        mape_pct=('relative_error_pct', 'mean'),
        rmse=('residual', lambda r: np.sqrt(np.mean(r**2))),
        mean_residual_bias=('residual', 'mean'),
        std_residual_bias=('residual', 'std')
    ).reset_index()

    print("=== Performance Comparison: Single-season vs. Multi-season Districts ===")
    display(comparison_summary.round(4))
