    # Blue indicates overprediction (Observed < Predicted, negative residual)
    max_val = max(abs(map_residuals_df['mean_residual_bias'].min()), abs(map_residuals_df['mean_residual_bias'].max()))

    sc = plt.scatter(
        map_residuals_df['longitude'],
        map_residuals_df['latitude'],
        c=map_residuals_df['mean_residual_bias'],
        cmap='seismic',
        vmin=-max_val,
        vmax=max_val,
        s=150,
        edgecolors='k',
        alpha=0.9
    )

    # Annotate district names for those with high magnitude of bias
    for idx, row in map_residuals_df.iterrows():
        if abs(row['mean_residual_bias']) > 0.25:
            plt.annotate(
                row['district'],
                (row['longitude'], row['latitude']),
                textcoords="offset points",
                xytext=(0, 10),
                ha='center',
                fontsize=8,
                bbox=dict(boxstyle="round,pad=0.2", fc="white", alpha=0.7, ec="gray", lw=0.5)
            )

    plt.colorbar(sc, label='Mean Residual Bias (Observed - Predicted Yield in t/ha)')
    plt.title('Spatial Distribution of Maize Yield Prediction Residual Bias by District', fontsize=14)
    plt.xlabel('Longitude')
    plt.ylabel('Latitude')
    plt.grid(True, linestyle=':', alpha=0.5)

    # Draw a baseline line at 0 bias conceptually
    plt.tight_layout()
    plt.show()
