import pandas as pd
import numpy as np

if 'district_perf' in globals() and 'coords_df' in globals():
    # Merge coordinates to perform geographic region classification
    df_regional = pd.merge(district_perf, coords_df, on='district', how='inner')

    # Classify districts into simple geographic quadrants/regions based on coordinates
    # Zambia coordinate ranges in dataset: Lon ~28.8 to 31.2, Lat ~-13.9 to -12.1
    lon_mid = df_regional['longitude'].median()
    lat_mid = df_regional['latitude'].median()

    def assign_region(row):
        if row['latitude'] > lat_mid: # More northern (less negative)
            return 'North-East' if row['longitude'] > lon_mid else 'North-West'
        else: # More southern (more negative)
            return 'South-East' if row['longitude'] > lon_mid else 'South-West'

    df_regional['Region'] = df_regional.apply(assign_region, axis=1)

    # Rank districts globally
    df_regional = df_regional.sort_values('mean_absolute_error').reset_index(drop=True)

    print("=== REGIONAL SUMMARY OF MODEL ERROR (MAE t/ha) ===")
    regional_summary = df_regional.groupby('Region').agg(
        district_count=('district', 'count'),
        mean_mae=('mean_absolute_error', 'mean'),
        min_mae=('mean_absolute_error', 'min'),
        max_mae=('mean_absolute_error', 'max'),
        best_district=('district', 'first'),
        worst_district=('district', 'last')
    ).round(4)

    display(regional_summary)

    print("\n=== TOP 3 PERFORMERS BY REGION ===")
    for region, group in df_regional.groupby('Region'):
        print(f"\nRegion: {region}")
        display(group.head(3)[['district', 'mean_observed_yield', 'mean_absolute_error', 'mean_residual_bias']].round(4))
else:
    print("district_perf or coords_df is missing in the kernel state.")

import matplotlib.pyplot as plt
import seaborn as sns

if 'df_regional' in globals() and not df_regional.empty:
    # Select relevant numerical columns for correlation analysis
    cols_to_corr = [
        'mean_absolute_error',
        'mean_observed_yield',
        'mean_predicted_yield',
        'mean_residual_bias',
        'longitude',
        'latitude'
    ]

    # Calculate the correlation matrix
    corr_matrix = df_regional[cols_to_corr].corr()

    # Generate a heatmap
    plt.figure(figsize=(8, 6))
    sns.heatmap(
        corr_matrix,
        annot=True,
        cmap='coolwarm',
        vmin=-1,
        vmax=1,
        fmt='.3f',
        linewidths=0.5,
        cbar_kws={'label': 'Correlation Coefficient'}
    )

    plt.title('Correlation Heatmap: MAE vs Geographic and Yield Metrics', fontsize=13, pad=15)
    plt.tight_layout()
    plt.show()
else:
    print("df_regional dataset is missing in the kernel state.")

import pandas as pd
import numpy as np
import matplotlib.pyplot as plt
import seaborn as sns
from scipy.stats import linregress

if 'out' in globals() and not out.empty and 'coords_df' in globals():
    # Filter to evaluations where we have actual observed yields
    eval_df = out.dropna(subset=['observed_yield_t_ha', 'pred_yield_t_ha']).copy()
    eval_df['residual'] = eval_df['observed_yield_t_ha'] - eval_df['pred_yield_t_ha']

    # Merge with coordinates to get longitude
    reg_df = pd.merge(eval_df, coords_df, on='district', how='inner')

    # Extract variables
    x = reg_df['longitude'].to_numpy()
    y = reg_df['residual'].to_numpy()

    # Perform linear regression
    slope, intercept, r_value, p_value, std_err = linregress(x, y)

    print("=== Regression Analysis: Longitude vs Prediction Residuals ===")
    print(f"Equation: Residual = {slope:.4f} * Longitude + ({intercept:.4f})")
    print(f"Pearson Correlation (r): {r_value:.4f}")
    print(f"Coefficient of Determination (R²): {r_value**2:.4f}")
    print(f"P-value: {p_value:.4e}")
    print(f"Standard Error: {std_err:.4f}")

    # Plotting
    plt.figure(figsize=(9, 6))
    sns.scatterplot(
        x='longitude',
        y='residual',
        data=reg_df,
        alpha=0.6,
        edgecolor='k',
        color='indigo',
        s=50,
        label='District-Season Residuals'
    )

    # Add regression line
    x_range = np.linspace(x.min(), x.max(), 100)
    y_pred = slope * x_range + intercept
    plt.plot(x_range, y_pred, color='darkorange', linestyle='-', linewidth=2.5, label='Fitted Regression Line')

    # Zero bias reference line
    plt.axhline(0, color='black', linestyle='--', alpha=0.5)

    # Annotate stats on plot
    stats_text = f"Slope: {slope:.4f}\nIntercept: {intercept:.4f}\nr: {r_value:.3f}\np-val: {p_value:.2e}"
    plt.gca().text(0.05, 0.05, stats_text, transform=plt.gca().transAxes, fontsize=11,
                    verticalalignment='bottom', bbox=dict(boxstyle='round,pad=0.5', facecolor='white', alpha=0.8, edgecolor='gray'))

    plt.title('Regression Analysis: Longitude vs. Yield Prediction Residuals', fontsize=13)
    plt.xlabel('Longitude', fontsize=11)
    plt.ylabel('Residual (Observed - Predicted Yield in t/ha)', fontsize=11)
    plt.grid(True, linestyle=':', alpha=0.6)
    plt.legend(loc='upper right')
    plt.tight_layout()
    plt.show()
else:
    print("Required data ('out' or 'coords_df') is missing in the kernel state.")

