# Filter to a specific season for visualization and export (e.g., 2022 season)
export_season = 2022
season_df = pred_df[pred_df['season'] == export_season].copy()

print(f"Loaded {len(season_df)} district predictions for season {export_season}")

# 2. Fetch spatial boundaries using geopandas
