geojson_url = "https://raw.githubusercontent.com/datasets/geo-boundaries/master/data/admin2.geojson"
# We will use geopandas natural earth or generate district polygons using the coordinate centers in our cached metadata
# to ensure the code executes safely even in offline/dry_run mode.

# Construct mock spatial geometries from our coordinate centers (centres.json) to simulate boundaries
boundary_features = []
from shapely.geometry import Point

for district_name, pts in centres.items():
    if len(pts) > 0:
        pts_arr = np.array(pts)
        mean_lon = pts_arr[:, 0].mean()
        mean_lat = pts_arr[:, 1].mean()
        # Create a small representative square geometry for the district area for rasterization demo
        pt = Point(mean_lon, mean_lat)
        # Buffer point to approximate a district polygon (~30km radius)
        poly = pt.buffer(0.35)
        boundary_features.append({'district': district_name, 'geometry': poly})

gdf_districts = gpd.GeoDataFrame(boundary_features, crs="EPSG:4326")

# Reproject to UTM Zone 35S matching the pipeline CRS
gdf_districts_utm = gdf_districts.to_crs(CRS)
print(f"Created spatial boundaries for {len(gdf_districts_utm)} districts in projection {CRS}")

# 3. Join predictions to spatial boundaries
spatial_predictions = gdf_districts_utm.merge(season_df, on='district', how='inner')
print(f"Successfully joined {len(spatial_predictions)} spatial features with prediction data.")

# 4. Rasterize predictions onto a 20m grid
