# Rasterize district polygons with crop yield values
raster_grid = rasterize(
    shapes=shapes,
    out_shape=(height, width),
    transform=transform,
    fill=0,       # No-data background value
    all_touched=True,
    dtype=np.float32
)

# Save raster grid as GeoTIFF
