import os
import numpy as np
import pandas as pd
import tensorflow as tf
from tensorflow.keras import layers, models, regularizers, callbacks
from sklearn.metrics import r2_score, mean_squared_error, mean_absolute_error

# =====================================================================
# 1. CORE PIPELINE ARCHITECTURE, TRAINING, AND SCORING DEFINITIONS
# =====================================================================

def load_cells(cell_list):
    xs, meta = []
    for d, s in cell_list:
        p = os.path.join(CACHE_DIR, f"{d.lower().replace(' ', '')}__{s}.npz")
        if not os.path.exists(p):
            continue
        z = np.load(p)
        xs.append(z['x'])
        # Include coordinate features in metadata load
        ct = z['centres'] if 'centres' in z else np.zeros((len(z['x']), 2))
        for k in range(len(z['x'])):
            meta.append((d, s, k, float(z['valid'][k].mean()), float(ct[k][0]), float(ct[k][1])))
    X = np.concatenate(xs) if xs else np.zeros((0, T, PATCH, PATCH, len(BANDS)), np.float16)
    M = pd.DataFrame(meta, columns=['gb_district', 'season', 'patch', 'valid_frac', 'lon', 'lat'])
    return X, M

def metrics(obs, pred):
    obs, pred = np.asarray(obs, float), np.asarray(pred, float)
    import math
    return {'n': int(len(obs)) * 1,
            'r2': float(r2_score(obs, pred)) if len(obs) > 1 else float('nan'),
            'rmse': float(math.sqrt(mean_squared_error(obs, pred))),
            'mae': float(mean_absolute_error(obs, pred))}

class TemporalAttention(layers.Layer):
    def __init__(self, **kwargs):
        super(TemporalAttention, self).__init__(**kwargs)
    def build(self, input_shape):
        feature_dim = input_shape[-1]
        self.W = self.add_weight(name="att_weight", shape=(feature_dim, 1),
                                 initializer="glorot_uniform", trainable=True)
        self.b = self.add_weight(name="att_bias", shape=(input_shape[1], 1),
                                 initializer="zeros", trainable=True)
        super(TemporalAttention, self).build(input_shape)

    @tf.function(reduce_retracing=True)
    def call(self, x):
        score = tf.tanh(tf.tensordot(x, self.W, axes=[-1, 0]) + self.b)
        attention_weights = tf.nn.softmax(score, axis=1)
        context = x * attention_weights
        context = tf.reduce_sum(context, axis=1)
        return context, attention_weights

def build_coordinate_fused_attention_model(static_dim=2):
    reg = regularizers.l2(1e-3)
    # Branch 1: Spatio-Temporal Sentinel-2 Imagery
    img_input = layers.Input((T, PATCH, PATCH, len(BANDS)), name='s2_windows')
    enc = models.Sequential(name='cnn_encoder', layers=[
        layers.Input((PATCH, PATCH, len(BANDS))),
        layers.Conv2D(32, 3, padding='same', kernel_regularizer=reg),
        layers.BatchNormalization(), layers.Activation('relu'), layers.MaxPooling2D(),
        layers.Conv2D(64, 3, padding='same', kernel_regularizer=reg),
        layers.BatchNormalization(), layers.Activation('relu'), layers.MaxPooling2D(),
        layers.Conv2D(128, 3, padding='same', kernel_regularizer=reg),
        layers.BatchNormalization(), layers.Activation('relu'),
        layers.GlobalAveragePooling2D(),
        layers.Dropout(0.5),
    ])
    img_features = layers.TimeDistributed(enc, name='td_cnn')(img_input)
    x = layers.Bidirectional(layers.LSTM(128, return_sequences=True, dropout=0.3, kernel_regularizer=reg))(img_features)
    x = layers.Bidirectional(layers.LSTM(64, return_sequences=True, dropout=0.3, kernel_regularizer=reg))(x)
    temporal_context, _ = TemporalAttention(name='temporal_attention')(x)

    # Branch 2: Static Geographic Features (Lat/Lon)
    coord_input = layers.Input(shape=(static_dim,), name='static_coordinates')
    coord_features = layers.Dense(16, activation='relu', kernel_regularizer=reg)(coord_input)
    coord_features = layers.BatchNormalization()(coord_features)

    # Branch Fusion & Output Regressor Head
    fused = layers.concatenate([temporal_context, coord_features], name='spatial_temporal_fusion')
    fused_dense = layers.Dense(64, activation='relu', kernel_regularizer=reg)(fused)
    fused_dense = layers.Dropout(0.5)(fused_dense)
    out = layers.Dense(1, name='yield_std')(fused_dense)

    model = models.Model(inputs=[img_input, coord_input], outputs=out, name='v29_coord_fused_attention')
    model.compile(optimizer=tf.keras.optimizers.Adam(LR), loss='mse')
    return model

def split_val(train_idx, frac=0.1):
    tr_cells = globals()['meta'].cell.iloc[train_idx].unique()
    rng = np.random.default_rng(SEED)
    val_cells = set(rng.choice(tr_cells, max(1, int(len(tr_cells) * frac)), replace=False))
    in_val = globals()['meta'].cell.iloc[train_idx].isin(val_cells).to_numpy()
    return train_idx[~in_val], train_idx[in_val]

def band_stats(Xtr, n_sample=4000):
    idx = np.random.default_rng(SEED).choice(len(Xtr), min(n_sample, len(Xtr)), replace=False)
    px = Xtr[idx].astype(np.float32).reshape(-1, len(BANDS))
    px = px[np.any(px != 0, axis=1)]
    return px.mean(0), px.std(0) + 1e-6

def make_ds(Xs, coords, ys, mean, std, train):
    mean_t, std_t = tf.constant(mean, tf.float32), tf.constant(std, tf.float32)
    def prep(x, coord, y):
        x = tf.cast(x, tf.float32)
        ok = tf.cast(tf.reduce_any(tf.not_equal(x, 0.0), -1, keepdims=True), tf.float32)
        x = (x - mean_t) / std_t * ok
        if train:
            k = tf.random.uniform([], 0, 4, tf.int32)
            x = tf.image.rot90(x, k)
            x = tf.cond(tf.random.uniform([]) < 0.5, lambda: tf.image.flip_left_right(x), lambda: x)
        return {"s2_windows": x, "static_coordinates": tf.cast(coord, tf.float32)}, y
    ds = tf.data.Dataset.from_tensor_slices((Xs, coords, ys))
    if train:
        ds = ds.shuffle(len(Xs), seed=SEED, reshuffle_each_iteration=True)
    return ds.map(prep, num_parallel_calls=tf.data.AUTOTUNE).batch(BATCH).prefetch(tf.data.AUTOTUNE)

def train_eval(train_idx, test_idx, out_dir, Xsrc=None, msrc=None):
    os.makedirs(out_dir, exist_ok=True)
    Xsrc = globals()['X'] if Xsrc is None else Xsrc
    msrc = globals()['meta'] if msrc is None else msrc
    tr, va = split_val(train_idx)
    mean, std = band_stats(globals()['X'][tr])
    y_all = globals()['y_all']
    y_mu, y_sd = y_all[tr].mean(), y_all[tr].std()
    ys = lambda i: ((y_all[i] - y_mu) / y_sd).astype(np.float32)

    # Retrieve target static coordinates (lon, lat)
    coords_tr = msrc.iloc[tr][['lon', 'lat']].to_numpy(np.float32)
    coords_va = msrc.iloc[va][['lon', 'lat']].to_numpy(np.float32)
    coords_te = msrc.iloc[test_idx][['lon', 'lat']].to_numpy(np.float32)

    tf.keras.backend.clear_session(); tf.random.set_seed(SEED)
    model = build_coordinate_fused_attention_model()
    ckpt = os.path.join(out_dir, 'best_model.keras')
    hist = model.fit(
        make_ds(globals()['X'][tr], coords_tr, ys(tr), mean, std, True),
        validation_data=make_ds(globals()['X'][va], coords_va, ys(va), mean, std, False),
        epochs=EPOCHS, verbose=2, shuffle=False,
        callbacks=[callbacks.EarlyStopping(patience=PATIENCE, restore_best_weights=True),
                   callbacks.ReduceLROnPlateau(factor=0.5, patience=8, min_lr=1e-5),
                   callbacks.ModelCheckpoint(ckpt, save_best_only=True)])
    pd.DataFrame(hist.history).to_csv(os.path.join(out_dir, 'history.csv'), index_label='epoch')

    zero_y = np.zeros(len(test_idx), np.float32)
    p_std = model.predict(make_ds(Xsrc[test_idx], coords_te, zero_y, mean, std, False), verbose=0).ravel()
    p_raw = p_std * y_sd + y_mu
    pt = msrc.iloc[test_idx][['gb_district', 'season', 'cell']].copy()
    pt['pred_raw'] = p_raw
    cell = pt.groupby(['cell', 'gb_district', 'season'], as_index=False)['pred_raw'].mean()
    cell['pred'] = cell['pred_raw'].clip(*CLIP)
    diag = {'pre_clip_min': float(cell.pred_raw.min()), 'pre_clip_max': float(cell.pred_raw.max()),
            'n_outside_clip': int(((cell.pred_raw < CLIP[0]) | (cell.pred_raw > CLIP[1])).sum()),
            'epochs_run': len(hist.history['loss']),
            'best_val_loss': float(min(hist.history['val_loss'])),
            'n_train_patches': int(len(tr)), 'n_val_patches': int(len(va)),
            'y_mean_train': float(y_mu), 'y_std_train': float(y_sd)}
    return cell, diag

globals()['load_cells'] = load_cells
globals()['metrics'] = metrics
globals()['train_eval'] = train_eval

