import matplotlib.pyplot as plt
import seaborn as sns
import scipy.stats as stats
import pandas as pd
import numpy as np
import os
import json

# --- Clean & Direct Authentic Regional Data Ingestion ---
RESULTS_DIR = globals().get('RESULTS_DIR', '/content/drive/MyDrive/MaizeYieldPrediction/results/v29_cnn_lstm_all_s2_bands')
pred_path = os.path.join(RESULTS_DIR, 'predictions_all_districts.csv')
coords_path = '/content/drive/MyDrive/MaizeYieldPrediction/v29_patches/centres.json'

if os.path.exists(pred_path) and os.path.exists(coords_path):
    # Load authentic predictions and compute MAE per district directly
    eval_df = pd.read_csv(pred_path).dropna(subset=['observed_yield_t_ha', 'pred_yield_t_ha'])
    eval_df['abs_error'] = (eval_df['observed_yield_t_ha'] - eval_df['pred_yield_t_ha']).abs()
    district_mae = eval_df.groupby('district')['abs_error'].mean().reset_index(name='mean_absolute_error')

    # Load authentic coordinates from Drive
    with open(coords_path, 'r') as f:
        c_data = json.load(f)
    coords = pd.DataFrame([
        {'district': k, 'longitude': np.mean([p[0] for p in v]), 'latitude': np.mean([p[1] for p in v])}
        for k, v in c_data.items() if v
    ])

    # Merge and assign geographic regions authentically
    df_clean = pd.merge(district_mae, coords, on='district', how='inner')
    if df_clean.empty:
         raise ValueError("No overlapping districts found between predictions and coordinates.")

    lon_mid = df_clean['longitude'].median()
    lat_mid = df_clean['latitude'].median()
    df_clean['Region'] = df_clean.apply(
        lambda r: ('North-East' if r['longitude'] > lon_mid else 'North-West')
        if r['latitude'] > lat_mid else
        ('South-East' if r['longitude'] > lon_mid else 'South-West'), axis=1
    )
    # Register reconstructed regional data globally for other cells
    globals()['df_regional'] = df_clean
else:
    raise FileNotFoundError(f"Authentic pipeline records missing. Ensure {pred_path} and {coords_path} exist on Drive first.")

# --- Plotting ---
plt.figure(figsize=(10, 6))

# Boxplot of MAE by Region
sns.boxplot(
    data=df_clean,
    x='Region',
    y='mean_absolute_error',
    palette='Set2',
    hue='Region',
    legend=False
)

# Add individual data points (stripplot)
sns.stripplot(
    data=df_clean,
    x='Region',
    y='mean_absolute_error',
    color='black',
    alpha=0.6,
    size=6,
    jitter=True
)

plt.title('Distribution of District MAE by Region (Authentic Data)', fontsize=15)
plt.xlabel('Geographic Region', fontsize=12)
plt.ylabel('Mean Absolute Error (t/ha)', fontsize=12)
plt.grid(axis='y', linestyle=':', alpha=0.7)
plt.tight_layout()
plt.show()

# Perform One-way ANOVA to check for significant differences
groups = [group['mean_absolute_error'].values for name, group in df_clean.groupby('Region') if len(group['mean_absolute_error'].values) > 0]
if len(groups) > 1:
    f_stat, p_val = stats.f_oneway(*groups)

    print("=== Regional ANOVA Test ===")
    print(f"F-statistic: {f_stat:.4f}")
    print(f"p-value: {p_val:.4e}")

    if p_val < 0.05:
        print("\nConclusion: There is a statistically significant difference in model performance (MAE) across regions.")
    else:
        print("\nConclusion: There is NO statistically significant difference in model performance (MAE) across regions.")
else:
    print("Not enough regional groups to perform ANOVA.")

import pandas as pd
import numpy as np
import matplotlib.pyplot as plt
import seaborn as sns
from sklearn.metrics import mean_squared_error

if 'full_cv_summary' in globals() and 'meta' in globals() and 'df_regional' in globals() and 'cell_obs' in globals():
    if 'left_out_group' not in full_cv_summary.columns:
        print("Error: The 'left_out_group' column is missing from the full_cv_summary DataFrame.")
        print("Available columns are:", full_cv_summary.columns.tolist())
    else:
        # Reconstruct the joint cv groups
        region_map = df_regional.set_index('district')['Region'].to_dict()
        cv_df = meta.copy()
        cv_df['region'] = cv_df['gb_district'].map(region_map)
        cv_df['st_group'] = cv_df['region'] + "_" + cv_df['season'].astype(str)

        baseline_results = []
        for grp in full_cv_summary['left_out_group']:
            test_mask = cv_df['st_group'] == grp
            tr_idx = np.where(~test_mask)[0]
            te_idx = np.where(test_mask)[0]

            # The baseline predictor is the mean yield of the training cells
            train_cells_obs = cell_obs[cell_obs.cell.isin(cv_df.cell.iloc[tr_idx])].obs
            test_cells_obs = cell_obs[cell_obs.cell.isin(cv_df.cell.iloc[te_idx])].obs

            # Create a naive baseline prediction
            baseline_pred = np.full(len(test_cells_obs), train_cells_obs.mean())

            # Evaluate baseline
            b_rmse = np.sqrt(mean_squared_error(test_cells_obs, baseline_pred))
            baseline_results.append({'left_out_group': grp, 'baseline_rmse': b_rmse})

        b_df = pd.DataFrame(baseline_results)
        comp_df = pd.merge(full_cv_summary, b_df, on='left_out_group')

        # Visual Comparison
        plt.figure(figsize=(15, 6))
        x = np.arange(len(comp_df))
        width = 0.4

        plt.bar(x - width/2, comp_df['model_rmse'], width, label='Attention CNN-LSTM Model', color='royalblue', edgecolor='black')
        plt.bar(x + width/2, comp_df['baseline_rmse'], width, label='Statistical Baseline (Train Mean)', color='lightcoral', edgecolor='black')

        plt.title('Attention Model vs. Statistical Baseline RMSE by Spatial-Temporal Block', fontsize=14)
        plt.xlabel('Left Out Group (Region_Season)', fontsize=12)
        plt.ylabel('RMSE (t/ha) - Lower is Better', fontsize=12)
        plt.xticks(x, comp_df['left_out_group'], rotation=45, ha='right')
        plt.legend()
        plt.grid(axis='y', linestyle=':', alpha=0.7)
        plt.tight_layout()
        plt.show()

        # Print Summary
        mean_model_rmse = comp_df['model_rmse'].mean()
        mean_baseline_rmse = comp_df['baseline_rmse'].mean()
        improvement = ((mean_baseline_rmse - mean_model_rmse) / mean_baseline_rmse) * 100

        print("=== Comparison Summary ===")
        print(f"Average Attention Model RMSE: {mean_model_rmse:.4f} t/ha")
        print(f"Average Statistical Baseline RMSE: {mean_baseline_rmse:.4f} t/ha")
        print(f"Overall Improvement over Baseline: {improvement:.2f}%")

else:
    print("Required data (full_cv_summary, meta, df_regional, cell_obs) is missing.")

import pandas as pd
import matplotlib.pyplot as plt
import seaborn as sns
import numpy as np
from sklearn.metrics import mean_squared_error

# Safely verify and build the correct comparison dataframe using active workspace variables
if 'full_cv_summary' in globals() and 'meta' in globals() and 'df_regional' in globals() and 'cell_obs' in globals():
    if 'left_out_group' not in full_cv_summary.columns:
        print("Error: The 'left_out_group' column is missing from the full_cv_summary DataFrame.")
        print("Available columns are:", full_cv_summary.columns.tolist())
    else:
        region_map = df_regional.set_index('district')['Region'].to_dict()
        cv_df = meta.copy()
        cv_df['region'] = cv_df['gb_district'].map(region_map)
        cv_df['st_group'] = cv_df['region'] + "_" + cv_df['season'].astype(str)

        baseline_results = []
        for grp in full_cv_summary['left_out_group']:
            test_mask = cv_df['st_group'] == grp
            tr_idx = np.where(~test_mask)[0]
            te_idx = np.where(test_mask)[0]

            train_cells_obs = cell_obs[cell_obs.cell.isin(cv_df.cell.iloc[tr_idx])].obs
            test_cells_obs = cell_obs[cell_obs.cell.isin(cv_df.cell.iloc[te_idx])].obs
            baseline_pred = np.full(len(test_cells_obs), train_cells_obs.mean())
            b_rmse = np.sqrt(mean_squared_error(test_cells_obs, baseline_pred))
            baseline_results.append({'left_out_group': grp, 'baseline_rmse': b_rmse})

        b_df = pd.DataFrame(baseline_results)
        plot_prep_df = pd.merge(full_cv_summary, b_df, on='left_out_group')
        plot_prep_df['region'] = plot_prep_df['left_out_group'].apply(lambda x: x.split('_')[0])
        plot_prep_df['season'] = plot_prep_df['left_out_group'].apply(lambda x: x.split('_')[1])

        # Melt the correctly configured dataframe
        plot_df = plot_prep_df.melt(
            id_vars=['region', 'season'],
            value_vars=['model_rmse', 'baseline_rmse'],
            var_name='Model Type',
            value_name='RMSE'
        )

        # Rename values for the legend
        plot_df['Model Type'] = plot_df['Model Type'].map({
            'model_rmse': 'Attention CNN-LSTM',
            'baseline_rmse': 'Statistical Baseline'
        })

        plt.figure(figsize=(10, 6))
        sns.barplot(
            data=plot_df,
            x='region',
            y='RMSE',
            hue='Model Type',
            palette={'Attention CNN-LSTM': 'royalblue', 'Statistical Baseline': 'lightcoral'},
            edgecolor='black',
            capsize=0.05
        )

        plt.title('Model vs. Baseline RMSE by Geographic Region', fontsize=14)
        plt.xlabel('Geographic Region', fontsize=12)
        plt.ylabel('RMSE (t/ha)', fontsize=12)
        plt.grid(axis='y', linestyle=':', alpha=0.7)
        plt.legend(title='Model', fontsize=11)
        plt.tight_layout()
        plt.show()

        # Calculate regional improvement summary
        reg_summary = plot_prep_df.groupby('region')[['model_rmse', 'baseline_rmse']].mean()
        reg_summary['Improvement (t/ha)'] = reg_summary['baseline_rmse'] - reg_summary['model_rmse']
        reg_summary['Improvement (%)'] = (reg_summary['Improvement (t/ha)'] / reg_summary['baseline_rmse']) * 100

        print("=== Regional RMSE Comparison Summary ===")
        display(reg_summary.round(4))
