"""### 15. Novel Architecture: Attention CNN-LSTM
This block implements a Vision Transformer tailored for multi-spectral time-series satellite imagery. It replaces the CNN-LSTM sequence by extracting spatial patches, adding spatio-temporal positional encodings, and processing the sequence via Multi-Head Self Attention.
"""

import tensorflow as tf
from tensorflow.keras import layers, models, regularizers

class TransformerEncoder(layers.Layer):
    def __init__(self, embed_dim, num_heads, dense_dim, **kwargs):
        super(TransformerEncoder, self).__init__(**kwargs)
        self.embed_dim = embed_dim
        self.num_heads = num_heads
        self.dense_dim = dense_dim
        self.attention = layers.MultiHeadAttention(num_heads=num_heads, key_dim=embed_dim)
        self.dense_proj = models.Sequential([
            layers.Dense(dense_dim, activation="gelu"),
            layers.Dense(embed_dim),
        ])
        self.layernorm_1 = layers.LayerNormalization(epsilon=1e-6)
        self.layernorm_2 = layers.LayerNormalization(epsilon=1e-6)

    def call(self, inputs, training=False):
        attention_output = self.attention(inputs, inputs)
        proj_input = self.layernorm_1(inputs + attention_output)
        proj_output = self.dense_proj(proj_input)
        return self.layernorm_2(proj_input + proj_output)

class SpatioTemporalTokenization(layers.Layer):
    def __init__(self, time_steps, patch_size, embed_dim, **kwargs):
        super(SpatioTemporalTokenization, self).__init__(**kwargs)
        self.time_steps = time_steps
        self.patch_size = patch_size
        self.embed_dim = embed_dim
        # Use a 3D convolution to extract non-overlapping spatio-temporal patches
        # Kernel size (1, patch_size, patch_size) means we extract spatial patches per time step
        self.projection = layers.Conv3D(
            filters=embed_dim,
            kernel_size=(1, patch_size, patch_size),
            strides=(1, patch_size, patch_size),
            padding="VALID"
        )

    def call(self, images):
        # images shape: (batch, T, H, W, Channels)
        patches = self.projection(images)
        # Flatten spatial dimensions: (batch, T, num_patches, embed_dim)
        batch_size = tf.shape(patches)[0]
        num_patches = tf.shape(patches)[2] * tf.shape(patches)[3]
        patches = tf.reshape(patches, (batch_size, self.time_steps * num_patches, self.embed_dim))
        return patches

class PositionalEmbedding(layers.Layer):
    def __init__(self, max_len, embed_dim, **kwargs):
        super(PositionalEmbedding, self).__init__(**kwargs)
        self.pos_emb = layers.Embedding(input_dim=max_len, output_dim=embed_dim)

    def call(self, x):
        maxlen = tf.shape(x)[1]
        positions = tf.range(start=0, limit=maxlen, delta=1)
        positions = self.pos_emb(positions)
        return x + positions

def build_vit_model():
    """
    Builds a Spatio-Temporal Vision Transformer.
    """
    # Safely get global constants
    T_val = globals().get('T', 8)
    PATCH_val = globals().get('PATCH', 32)
    BANDS_val = globals().get('FUSION_SAR_BANDS', ['B1', 'B2', 'B3', 'B4', 'B5', 'B6', 'B7', 'B8', 'B8A', 'B9', 'B11', 'B12', 'NDVI', 'EVI', 'precip', 'temp_max', 'temp_min', 'VV', 'VH', 'VV_VH_ratio'])
    LR_val = globals().get('LR', 1e-3)

    # Hyperparameters for ViT
    patch_size = 8  # 32x32 image / 8 = 4x4 = 16 patches per frame
    embed_dim = 128
    num_heads = 4
    transformer_layers = 3
    dense_dim = 256

    # Number of tokens = Time steps (12 or 8) * Spatial patches per frame (16)
    num_tokens = T_val * ((PATCH_val // patch_size) ** 2)

    inp = layers.Input(shape=(T_val, PATCH_val, PATCH_val, len(BANDS_val)), name='s2_windows')

    # 1. Tokenization
    x = SpatioTemporalTokenization(time_steps=T_val, patch_size=patch_size, embed_dim=embed_dim)(inp)

    # 2. Positional Embedding
    x = PositionalEmbedding(max_len=num_tokens, embed_dim=embed_dim)(x)
    x = layers.Dropout(0.2)(x)

    # 3. Transformer Encoder Blocks
    for _ in range(transformer_layers):
        x = TransformerEncoder(embed_dim, num_heads, dense_dim)(x)

    # 4. Global Average Pooling (aggregating token representations)
    x = layers.GlobalAveragePooling1D()(x)

    # 5. Regression Head
    x = layers.Dense(64, activation="gelu", kernel_regularizer=regularizers.l2(1e-4))(x)
    x = layers.Dropout(0.3)(x)
    out = layers.Dense(1, name="yield_std")(x)

    model = models.Model(inputs=inp, outputs=out, name='v29_spatiotemporal_vit')
    model.compile(optimizer=tf.keras.optimizers.Adam(LR_val), loss='mse')
    return model

# Instantiate and display the summary of the ViT model
vit_model = build_vit_model()
vit_model.summary()

"""To train this model instead of the CNN-LSTM, you simply need to update your `train_eval` function to call `build_vit_model()` instead of `build_novel_attention_model()`."""

