"""## 16. Early Prediction & Multi-Modal Data Fusion (VIs + Climate)

To predict yield **2 months before the harvest season** (assuming a typical May harvest in Zambia), we truncate the data collection window to end in late February. This reduces our time steps from 12 to 8.

We also inject **Vegetation Indices** (NDVI, EVI) and **Climate Data** (CHIRPS Precipitation, ERA5 Temperature) into the feature stack to provide the model with robust physiological and meteorological context.
"""

# 1. Early Prediction Configuration
# Stop at February (Months: Nov, Dec, Jan, Feb) -> 4 months = 8 bi-weekly windows
EARLY_SEASON_MONTHS = [11, 12, 1, 2]
T_EARLY = 2 * len(EARLY_SEASON_MONTHS)

# 2. Define New Feature Bands
BANDS = ['B1', 'B2', 'B3', 'B4', 'B5', 'B6', 'B7', 'B8', 'B8A', 'B9', 'B11', 'B12']
VI_BANDS = ['NDVI', 'EVI']
CLIMATE_BANDS = ['precip', 'temp_max', 'temp_min']

# Total fused bands (12 S2 + 2 VIs + 3 Climate = 17 Bands)
FUSION_BANDS = BANDS + VI_BANDS + CLIMATE_BANDS

print(f"Early Prediction Time Steps (T): {T_EARLY}")
print(f"Multi-Modal Feature Depth: {len(FUSION_BANDS)} bands")
print(f"Bands: {FUSION_BANDS}")

from datetime import date

# Ensure DRY_RUN is defined (defaults to False if the config cell wasn't run)
DRY_RUN = globals().get('DRY_RUN', False)

if not DRY_RUN:
    def early_windows(season):
        """Generates the 8 bi-weekly windows for the early prediction timeline."""
        out = []
        for m in EARLY_SEASON_MONTHS:
            y = season if m >= 11 else season + 1
            nxt = date(y + (m == 12), m % 12 + 1, 1)
            out.append((date(y, m, 1).isoformat(), date(y, m, 16).isoformat()))
            out.append((date(y, m, 16).isoformat(), nxt.isoformat()))
        return out

    def add_indices(img):
        """Calculates NDVI and EVI from Sentinel-2 bands."""
        # NDVI = (NIR - RED) / (NIR + RED)
        ndvi = img.normalizedDifference(['B8', 'B4']).rename('NDVI')

        # EVI = 2.5 * ((NIR - RED) / (NIR + 6 * RED - 7.5 * BLUE + 10000))
        evi = img.expression(
            '2.5 * ((NIR - RED) / (NIR + 6 * RED - 7.5 * BLUE + 10000))', {
                'NIR': img.select('B8'),
                'RED': img.select('B4'),
                'BLUE': img.select('B2')
        }).rename('EVI')

        return img.addBands([ndvi, evi])

    def patch_image_fusion(lon, lat, season):
        """
        Extracts Fused Sentinel-2, Vegetation Indices, and Climate Data.
        Resamples coarse climate grids (CHIRPS/ERA5) to the fine Sentinel-2 20m grid.
        """
        region = ee.Geometry.Point([lon, lat]).buffer(PATCH * SCALE)
        parts = []

        # Load Collections
        S2 = ee.ImageCollection('COPERNICUS/S2_SR_HARMONIZED')
        CHIRPS = ee.ImageCollection("UCSB-CHG/CHIRPS/DAILY")
        ERA5 = ee.ImageCollection("ECMWF/ERA5_LAND/DAILY_AGGR") # ERA5-Land is higher resolution than ERA5

        EMPTY_S2 = ee.Image.constant([0] * len(BANDS)).rename(BANDS).toFloat().updateMask(0)

        for t, (s, e) in enumerate(early_windows(season)):
            # 1. Process Sentinel-2 & VIs
            comp_s2 = (S2.filterBounds(region).filterDate(s, e).map(_mask)
                       .merge(ee.ImageCollection([EMPTY_S2])).median())
            comp_s2 = add_indices(comp_s2)

            valid_mask = comp_s2.select('B4').mask().gt(0).unmask(0).rename(f'w{t}_valid')
            parts.append(valid_mask)

            s2_vi_bands = comp_s2.select(BANDS + VI_BANDS).divide(10000).unmask(0)
            parts.append(s2_vi_bands.rename([f'w{t}_{b}' for b in BANDS + VI_BANDS]))

            # 2. Process Climate Data (Sum for Precipitation, Mean for Temp)
            precip = CHIRPS.filterBounds(region).filterDate(s, e).sum().unmask(0).rename(f'w{t}_precip')

            # ERA5-Land temps are in Kelvin. Subtract 273.15 to convert to Celsius.
            era5_temp = ERA5.filterBounds(region).filterDate(s, e).mean()
            t_max = era5_temp.select('temperature_2m_max').subtract(273.15).unmask(0).rename(f'w{t}_temp_max')
            t_min = era5_temp.select('temperature_2m_min').subtract(273.15).unmask(0).rename(f'w{t}_temp_min')

            # Resample climate datasets bilinearly to match Sentinel-2 scale smoothly
            climate_comp = ee.Image.cat([precip, t_max, t_min]) \
                             .resample('bilinear') \
                             .reproject(crs=CRS, scale=SCALE)

            parts.append(climate_comp.toFloat())

        return ee.Image.cat(parts).toFloat()

    print("✅ Successfully defined multi-modal Earth Engine extraction pipeline!")
    print("To use this, replace `patch_image` with `patch_image_fusion` in your data extraction loop, and update your model input shape to `(T_EARLY, PATCH, PATCH, len(FUSION_BANDS))`.")
else:
    print("DRY_RUN is active. Set DRY_RUN=False and re-run to initialize Earth Engine fusion functions.")

import os
