import tensorflow as tf
from tensorflow.keras import layers, models, regularizers, callbacks
import numpy as np

# 1. Update global hyperparameter references for better generalization
globals()['LR'] = 2e-4
globals()['BATCH'] = 32

def build_refined_attention_model():
    """
    Builds an optimized Attention-Augmented CNN-LSTM network designed to
    minimize spatial variance with increased dropout and L2 regularization.
    """
    reg = regularizers.l2(1.5e-4)  # Increased slightly to restrict spatial memorization

    # Spatial Encoder (2D CNN per frame)
    enc = models.Sequential(name='cnn_encoder', layers=[
        layers.Input((PATCH, PATCH, len(BANDS))),
        layers.Conv2D(32, 3, padding='same', kernel_regularizer=reg),
        layers.BatchNormalization(), layers.Activation('relu'), layers.MaxPooling2D(),
        layers.Conv2D(64, 3, padding='same', kernel_regularizer=reg),
        layers.BatchNormalization(), layers.Activation('relu'), layers.MaxPooling2D(),
        layers.Conv2D(128, 3, padding='same', kernel_regularizer=reg),
        layers.BatchNormalization(), layers.Activation('relu'),
        layers.GlobalAveragePooling2D(),
        layers.Dropout(0.4),  # Increased from 0.3 to 0.4 to prevent overfitting to local textures
    ])

    inp = layers.Input((T, PATCH, PATCH, len(BANDS)), name='s2_windows')

    # Time Distributed feature extraction
    x = layers.TimeDistributed(enc, name='td_cnn')(inp)

    # Sequential Processor (Bidirectional LSTM) with higher dropout thresholds
    x = layers.Bidirectional(layers.LSTM(128, return_sequences=True, dropout=0.3, kernel_regularizer=reg))(x)
    x = layers.Bidirectional(layers.LSTM(64, return_sequences=True, dropout=0.3, kernel_regularizer=reg))(x)

    # Temporal Attention Block
    context, att_weights = TemporalAttention(name='temporal_attention')(x)

    # Regressor Head
    x = layers.Dense(64, activation='relu', kernel_regularizer=reg)(context)
    x = layers.Dropout(0.4)(x)  # Increased from 0.3 to 0.4
    out = layers.Dense(1, name='yield_std')(x)

    model = models.Model(inputs=inp, outputs=out, name='v29_refined_attention_cnn_lstm')
    model.compile(optimizer=tf.keras.optimizers.Adam(LR), loss='mse')
    return model

# Override build model function in global namespace
globals()['build_novel_attention_model'] = build_refined_attention_model
print("Successfully refined CNN-LSTM parameters and registered the updated architecture!")

# Re-run cross-validation to observe the impact of the newly registered highly regularized model architecture
print("=== Starting cross-validation with Highly Regularized CNN-LSTM parameters ===")

