# Load 12-band datasets
def load_standard_cells(cell_list):
    xs, meta_list = [], []
    for d, s in cell_list:
        p = cell_path(d, s)
        if not os.path.exists(p):
            continue
        z = np.load(p)
        xs.append(z['x'])
        for k in range(len(z['x'])):
            meta_list.append((d, s, k, float(z['valid'][k].mean())))
    X_std = np.concatenate(xs) if xs else np.zeros((0, T, PATCH, PATCH, len(BANDS)), np.float16)
    M_std = pd.DataFrame(meta_list, columns=['gb_district', 'season', 'patch', 'valid_frac'])
    return X_std, M_std

X_std, meta_std = load_standard_cells(cells)
meta_std = meta_std.merge(labels.drop_duplicates(subset=['gb_district', 'season']), on=['gb_district', 'season'], how='left')
meta_std['cell'] = meta_std['gb_district'] + '|' + meta_std['season'].astype(str)
y_all_std = meta_std['yield_t_ha'].to_numpy(np.float32)

# Safely map 'lon' and 'lat' from 'coords_df' using 'gb_district' index
if 'coords_df' in globals():
    mapping = coords_df.set_index('district')[['longitude', 'latitude']].rename(columns={'longitude': 'lon', 'latitude': 'lat'})
    meta_std = meta_std.join(mapping, on='gb_district')
    meta_std['lon'] = meta_std['lon'].fillna(meta_std['lon'].median())
    meta_std['lat'] = meta_std['lat'].fillna(meta_std['lat'].median())

globals()['X'] = X_std
globals()['meta'] = meta_std
globals()['y_all'] = y_all_std

# Force the train_eval process to use the correct model function by overriding build_novel_attention_model
globals()['build_novel_attention_model'] = build_highly_regularized_model

# Run evaluation on both District and Season axes using the highly regularized model with Early Stopping
refined_summaries = {axis: run_axis(axis) for axis in AXES}

# Display summary comparisons
rows_refined = []
for axis, s in refined_summaries.items():
    if s and 'mean_r2' in s:
        rows_refined.append({
            'axis': axis,
            'model R2 (mean of folds)': round(s['mean_r2'], 3),
            '+/- std': round(s['std_r2'], 3),
            'baseline R2': round(s['mean_baseline_r2'], 3),
            'pooled RMSE t/ha': round(s['pooled']['rmse'], 3),
            'residual R2': round(s.get('mean_residual_r2', float('nan')), 3)
        })
import pandas as pd
