import pandas as pd
import numpy as np
import matplotlib.pyplot as plt
import seaborn as sns
import os

# Fallback configurations if configuration cells were not run
RESULTS_DIR = globals().get('RESULTS_DIR', '/content/drive/MyDrive/MaizeYieldPrediction/results/v29_cnn_lstm_all_s2_bands')
pred_csv_path = os.path.join(RESULTS_DIR, 'predictions_all_districts.csv')

