    sns.kdeplot(df_2027['pred_yield_t_ha'], label='2027 Season Forecast', fill=True, color='forestgreen', linewidth=2.5)
    plt.title('Yield Distribution Comparison: Historical vs. 2027 Forecast')
    plt.xlabel('Predicted Yield (t/ha)')
    plt.ylabel('Density')
    plt.legend()
    plt.grid(True, linestyle=':', alpha=0.6)
    plt.tight_layout()
    plt.show()

    # Show Top 10 highest and lowest predicted districts for 2027
    display_cols = ['district', 'pred_yield_t_ha']
    if 'valid_frac' in df_2027.columns:
        display_cols.append('valid_frac')

    print("\n=== Top 10 Districts with Highest Predicted Yields in 2027 ===")
    print(df_2027.sort_values(by='pred_yield_t_ha', ascending=False).head(10)[display_cols].to_string(index=False))

    print("\n=== Top 10 Districts with Lowest Predicted Yields in 2027 ===")
    print(df_2027.sort_values(by='pred_yield_t_ha', ascending=True).head(10)[display_cols].to_string(index=False))

