# Plot bar chart
fig, axes = plt.subplots(1, 2, figsize=(13, 5))

# R2 Plot
sns.barplot(x=['Attention CNN-LSTM', 'Random Forest Baseline'], y=[dl_r2, pooled_r2], ax=axes[0], palette='crest', hue=['Attention CNN-LSTM', 'Random Forest Baseline'], legend=False)
axes[0].set_title('Spatial R2 Comparison (Higher is Better)', fontsize=12, fontweight='bold')
axes[0].set_ylabel('R2 Score')
axes[0].grid(axis='y', linestyle=':')

# RMSE Plot
sns.barplot(x=['Attention CNN-LSTM', 'Random Forest Baseline'], y=[dl_rmse, pooled_rmse], ax=axes[1], palette='flare', hue=['Attention CNN-LSTM', 'Random Forest Baseline'], legend=False)
