import rasterio
from rasterio.transform import from_origin
import matplotlib.pyplot as plt
import numpy as np
import os

tif_path = '/content/sample_patch.tif'
png_path = '/content/sample_patch.png'

# Create a dummy TIFF if it doesn't exist so the demonstration runs
if not os.path.exists(tif_path):
    print(f"'{tif_path}' not found. Creating a synthetic sample patch...")
    dummy_data = np.random.rand(32, 32).astype(np.float32)
    transform = from_origin(28.0, -15.0, 20, 20)
    with rasterio.open(
        tif_path, 'w', driver='GTiff', height=32, width=32,
        count=1, dtype=dummy_data.dtype, crs='EPSG:32735', transform=transform
    ) as dst:
        dst.write(dummy_data, 1)

with rasterio.open(tif_path) as src:
    band = src.read(1)

    # Normalize the data for visualization
    band_min, band_max = np.nanmin(band), np.nanmax(band)
    if band_max > band_min:
        norm_band = (band - band_min) / (band_max - band_min)
    else:
        norm_band = np.zeros_like(band)

    # Save as PNG using a colormap
    plt.imsave(png_path, norm_band, cmap='YlGnBu')
    print(f"Successfully converted {tif_path} to {png_path}!")

