import geemap
import ee
from IPython.display import display

print(f"Initializing Map with Sentinel-2 View... Base: {map_background} | Filter: {cropland_filter}")

# Configure geemap Map instance
Map = geemap.Map(center=[-13.5, 27.8], zoom=6, toolbar_ctrl=False, ee_initialize=False)

# Handle base map background configuration
if map_background == "OpenStreetMap":
    try:
        Map.add_basemap('OpenStreetMap')
    except Exception:
        pass
elif map_background == "Transparent (No Background)":
    Map.clear_layers()

try:
    # Initialize GEE with configured project context
    project_id = globals().get('EE_PROJECT', 'cnn-lstm-crop-yield')
    try:
        ee.Initialize(project=project_id)
    except Exception:
        pass

    # Get GEE vector and raster datasets
    gb_districts = (ee.FeatureCollection('WM/geoLab/geoBoundaries/600/ADM2')
                    .filter(ee.Filter.eq('shapeGroup', 'ZMB')))

    # Fetch and filter Sentinel-2 True Color (Nov 2021 - Feb 2022)
    S2 = ee.ImageCollection('COPERNICUS/S2_SR_HARMONIZED') \
        .filterBounds(gb_districts.geometry()) \
        .filterDate('2021-11-01', '2022-02-28') \
        .filter(ee.Filter.lt('CLOUDY_PIXEL_PERCENTAGE', 20)) \
        .median()

    vis_params = {
        'bands': ['B4', 'B3', 'B2'],
        'min': 0,
        'max': 3000,
        'gamma': 1.4
    }

    # Overlay the Sentinel-2 true-color view clipped to Zambia boundaries
    Map.addLayer(S2.clip(gb_districts.geometry()), vis_params, 'Sentinel-2 (True Color View)')

    # Fetch cropland classification raster layer
    cropland = ee.ImageCollection('ESA/WorldCover/v200').first().select('Map').eq(40).selfMask()

    # Apply layer filtering criteria dynamically over Sentinel-2 background
    if cropland_filter == "Show All":
        Map.addLayer(cropland.clip(gb_districts.geometry()), {'palette': ['#f1c40f']}, 'ESA Cropland (Yellow Overlay)')
        Map.addLayer(gb_districts.style(color='white', fillColor='00000000', width=1.5), {}, 'Zambia District Boundaries')
    elif cropland_filter == "Show Cropland Only":
        Map.addLayer(cropland.clip(gb_districts.geometry()), {'palette': ['#2ecc71']}, 'Cropland (Green Mask)')
    elif cropland_filter == "Show Districts Only":
        Map.addLayer(gb_districts.style(color='white', fillColor='00000000', width=2), {}, 'Zambia Districts')

except Exception as e:
    print(f"Geospatial Layer Load Info: {e}")

globals()['Map'] = Map
display(Map)



