    years = np.arange(2017, 2027)
    districts = ["Choma", "Kazungula", "Luangwa", "Mansa", "Serenje", "Solwezi"]
    records = []
    np.random.seed(42)
    for y in years:
        for d in districts:
            base = 1.95 + 0.3 * np.sin(y / 4)
            records.append({'district': d, 'season': y, 'pred_yield_t_ha': float(np.clip(base + np.random.normal(0, 0.2), 0.5, 4.0))})
