df_mod_seq = df_mod_seq[(df_mod_seq['season'] >= 2017) & (df_mod_seq['season'] <= 2026)]

df_timeline = pd.concat([df_back_seq, df_mod_seq], ignore_index=True).sort_values('season').reset_index(drop=True)

