"""```markdown
## 23. Long-Term Multi-Satellite Harmonization (1997 - Present)
To extend our model's timeline back to **1997**, we ingest and combine records across three major satellite platforms:
1. **NOAA AVHRR (1997 - 2000)**: Coarse spatial resolution ($0.05^\circ$), high temporal coverage, corrected via NOAA Climate Data Record (CDR).
2. **MODIS (2000 - Present)**: Moderate resolution ($250\text{m}$), extracted from the `MODIS/061/MOD13Q1` collection.
3. **Landsat 5, 7, 8, 9 (1997 - Present)**: High spatial resolution ($30\text{m}$), harmonized across generations to match Landsat 8/9 Operational Land Imager (OLI) spectral characteristics.
```
"""

import ee
import pandas as pd
import numpy as np
from datetime import date

# Dynamic timeline definition
START_YEAR = 1997
END_YEAR = 2026
HARMONIZED_SEASONS = list(range(START_YEAR, END_YEAR + 1))
HARMONIZED_MONTHS = [11, 12, 1, 2, 3, 4]  # November to April

def get_harmonized_windows(season):
    """Generates 12 bi-weekly windows for any target year since 1997."""
    out = []
    for m in HARMONIZED_MONTHS:
        y = season if m >= 11 else season + 1
        nxt = date(y + (m == 12), m % 12 + 1, 1)
        out.append((date(y, m, 1).isoformat(), date(y, m, 16).isoformat()))
        out.append((date(y, m, 16).isoformat(), nxt.isoformat()))
    return out

def extract_landsat_ndvi(region, start_date, end_date):
    """Fetches and harmonizes Landsat collections (5, 7, 8, 9) to standard OLI NDVI."""
    # Landsat 8 & 9 (OLI)
    l89 = (ee.ImageCollection('LANDSAT/LC08/C02/T1_L2')
           .merge(ee.ImageCollection('LANDSAT/LC09/C02/T1_L2'))
           .filterBounds(region)
           .filterDate(start_date, end_date))

    def calc_l89_ndvi(img):
        ndvi = img.normalizedDifference(['SR_B5', 'w4_valid' if 'w4_valid' in img.bandNames().getInfo() else 'SR_B4']).rename('NDVI')
        return img.addBands(ndvi).select('NDVI')

    # Landsat 5 & 7 (TM/ETM+)
    l57 = (ee.ImageCollection('LANDSAT/LT05/C02/T1_L2')
           .merge(ee.ImageCollection('LANDSAT/LE07/C02/T1_L2'))
           .filterBounds(region)
           .filterDate(start_date, end_date))

    def calc_l57_ndvi(img):
        # Apply Roy et al. (2016) transfer functions to align TM/ETM+ with OLI NDVI spectral response
        ndvi = img.normalizedDifference(['SR_B4', 'SR_B3']).rename('NDVI')
        aligned_ndvi = ndvi.multiply(1.0807).add(0.002).rename('NDVI')
        return img.addBands(aligned_ndvi).select('NDVI')

    l89_processed = l89.map(calc_l89_ndvi)
    l57_processed = l57.map(calc_l57_ndvi)

    combined = l89_processed.merge(l57_processed).median().unmask(0)
    return combined.resample('bilinear').reproject(crs=CRS, scale=SCALE)

def extract_modis_ndvi(region, start_date, end_date):
    """Fetches MODIS MOD13Q1 250m NDVI and resamples to target coordinate grids."""
    modis = (ee.ImageCollection('MODIS/061/MOD13Q1')
             .filterBounds(region)
             .filterDate(start_date, end_date)
             .select('NDVI')
             .median()
             .multiply(0.0001)  # MOD13Q1 scale factor
             .unmask(0))
    return modis.resample('bilinear').reproject(crs=CRS, scale=SCALE)

def extract_noaa_avhrr_ndvi(region, start_date, end_date):
    """Fetches NOAA CDR AVHRR 0.05-degree NDVI and resamples smoothly."""
    avhrr = (ee.ImageCollection('NOAA/CDR/AVHRR/NDVI/V5')
             .filterBounds(region)
             .filterDate(start_date, end_date)
             .select('NDVI')
             .median()
             .multiply(0.0001)  # Scale factor correction
             .unmask(0))
    return avhrr.resample('bilinear').reproject(crs=CRS, scale=SCALE)

def extract_unified_longterm_phenology(lon, lat, season):
    """
    Aggregates multi-satellite sensors dynamically based on temporal operational ranges.
    Output Tensor: 12 bi-weekly windows tracking optimized harmonized NDVI.
    """
    region = ee.Geometry.Point([lon, lat]).buffer(PATCH * SCALE)
    parts = []

    for t, (s, e) in enumerate(get_harmonized_windows(season)):
        # Sensor selection logic based on target operational year
        if season < 2000:
            # Pre-MODIS era (Use NOAA AVHRR and Landsat 5)
            landsat_img = extract_landsat_ndvi(region, s, e)
            avhrr_img = extract_noaa_avhrr_ndvi(region, s, e)
            # Blend: Prefer Landsat 5 resolution, fallback to AVHRR if completely cloudy
            composite = landsat_img.where(landsat_img.eq(0), avhrr_img)
        elif season < 2013:
            # MODIS era (MODIS + Landsat 5/7)
            landsat_img = extract_landsat_ndvi(region, s, e)
            modis_img = extract_modis_ndvi(region, s, e)
            composite = landsat_img.where(landsat_img.eq(0), modis_img)
        else:
            # Modern OLI Era (Landsat 8/9 + MODIS)
            landsat_img = extract_landsat_ndvi(region, s, e)
            modis_img = extract_modis_ndvi(region, s, e)
            composite = landsat_img.where(landsat_img.eq(0), modis_img)

        parts.append(composite.rename(f'w{t}_NDVI'))

    return ee.Image.cat(parts).toFloat()

print("✅ Multi-satellite harmonization module (AVHRR/MODIS/Landsat) 1997-2026 successfully initialized!")

