"""## 📝 Mathematical Formulations & Hyperparameters: SAR-Augmented Attention CNN-LSTM

This section outlines the mathematical foundations governing each layer of the **Spatio-Temporal SAR-Augmented Attention CNN-LSTM** crop yield forecasting network, along with its hyperparameter configurations.

---

### 1. Spatial CNN Encoder Branch
For each bi-weekly sequence step $t \in \{1, \dots, T\}$, the spatial image patch input $\mathbf{X}_t \in \mathbb{R}^{H \times W \times C}$ (where $H=W=32$ and $C=20$ multi-modal bands) undergoes non-linear spatial feature extraction:

$$\mathbf{H}_t^{(l)} = \sigma \left( \mathbf{W}^{(l)} * \mathbf{H}_t^{(l-1)} + \mathbf{b}^{(l)} \right)$$

$$\mathbf{H}_t^{\text{GAP}} = \text{GlobalAveragePooling2D} \left( \mathbf{H}_t^{(L_c)} \right)$$

Where:
* $*$ represents the 2D spatial convolution operator.
* $\sigma(\cdot)$ represents the Rectified Linear Unit (ReLU) activation function.
* $\mathbf{W}^{(l)}$ and $\mathbf{b}^{(l)}$ are the kernel weights and biases for layer $l$, subject to $L_2$ regularization penalty $\lambda = 1.5 \times 10^{-3}$.
* Spatial Dropout is applied after each convolutional block with a rate of $0.40$ to zero out entire feature maps:
  $$P(y_{i,j,k} = 0) = 0.40$$

---

### 2. Bidirectional Recurrent Sequence Branch
The sequential vectors $\left( \mathbf{H}_1^{\text{GAP}}, \dots, \mathbf{H}_T^{\text{GAP}} \right)$ are processed by a stacked Bidirectional LSTM (BiLSTM) network to capture historical and forward phenological contexts:

$$\overrightarrow{\mathbf{h}}_t = \text{LSTM}_{\text{forward}} \left( \mathbf{H}_t^{\text{GAP}}, \overrightarrow{\mathbf{h}}_{t-1} \right)$$
$$\overleftarrow{\mathbf{h}}_t = \text{LSTM}_{\text{backward}} \left( \mathbf{H}_t^{\text{GAP}}, \overleftarrow{\mathbf{h}}_{t+1} \right)$$
$$\mathbf{h}_t = \left[ \overrightarrow{\mathbf{h}}_t \parallel \overleftarrow{\mathbf{h}}_t \right]$$

Where $\parallel$ denotes the concatenation operator. Recurrent gates are subject to recurrent dropout $d_{rec} = 0.20$ inside memory cells to prevent temporal overfitting.

---

### 3. Temporal Attention Mechanism
To dynamically weight the phenological windows without manual alignment, we define a trainable attention mechanism:

$$\mathbf{s}_t = \mathbf{w}^{\top} \tanh\left( \mathbf{W}_{att} \mathbf{h}_t + \mathbf{b}_{att} \right)$$

$$\alpha_t = \frac{\exp(\mathbf{s}_t)}{\sum_{j=1}^{T} \exp(\mathbf{s}_j)}$$

$$\mathbf{c} = \sum_{t=1}^{T} \alpha_t \mathbf{h}_t$$

Where:
* $\mathbf{W}_{att} \in \mathbb{R}^{D \times 2D_r}$ and $\mathbf{w} \in \mathbb{R}^{D \times 1}$ are learnable projection parameters.
* $\alpha_t$ represents the learned attention weight for window $t$, satisfying $\sum_{t} \alpha_t = 1$.
* $\mathbf{c}$ is the aggregated temporal context vector.

---

### 4. Static Coordinate Fusion & Inference Head
To incorporate geographic priors (Latitude and Longitude centroids $\mathbf{G} \in \mathbb{R}^{2}$), a coordinate dense branch is fused with the temporal sequence context:

$$\mathbf{f}_{coord} = \text{BatchNormalization} \left( \sigma \left( \mathbf{W}_{g} \mathbf{G} + \mathbf{b}_{g} \right) \right)$$

$$\mathbf{x}_{fused} = \left[ \mathbf{c} \parallel \mathbf{f}_{coord} \right]$$

$$\hat{y}_{std} = \mathbf{W}_{out} \left( \text{Dropout}_{0.45} \left( \sigma \left( \mathbf{W}_{f} \mathbf{x}_{fused} + \mathbf{b}_{f} \right) \right) \right) + b_{out}$$

Finally, the normalized target prediction is transformed back to physical crop yield space ($t/ha$):

$$\hat{y}_{t/ha} = \text{Clip}_{\left[0.5, 4.0\right]} \left( \hat{y}_{std} \cdot \sigma_{y_{\text{train}}} + \mu_{y_{\text{train}}} \right)$$

---

### 5. Consolidated Hyperparameter Table

| Hyperparameter Category | Metric / Structural Value |
| :--- | :--- |
| **S2 Multi-Spectral Bands** | $12$ bands (B1, B2, B3, B4, B5, B6, B7, B8, B8A, B9, B11, B12) |
| **Vegetation Indices** | $2$ indicators (NDVI, EVI) |
| **Climate Vectors** | $3$ variables (CHIRPS Precip, ERA5 Temp Max, Temp Min) |
| **Radar Polarizations** | $3$ bands (S1 GRD VV, VH, VV/VH cross-ratio) |
| **Sequence Length ($T$)** | $12$ bi-weekly windows (Nov - April) |
| **Cropland Spatial Patch Size** | $32 \times 32$ pixels ($640\,m$ footprint @ $20\,m$ resolution) |
| **Loss Regularization Penalty** | $L_2$ decay constant $\lambda = 1.5 \times 10^{-3}$ on conv layers |
| **Spatial Dropout Rate** | $0.40$ (drops entire 2D feature grids) |
| **Inference Head Dropout** | $0.45$ on concatenated bottleneck |
| **Base Learning Rate ($LR$)** | $2.0 \times 10^{-4}$ (stabilized Adam optimizer) |
| **Batch Size** | $32$ samples |
"""

