windows = [
    'Nov 1-15', 'Nov 16-30', 'Dec 1-15', 'Dec 16-31',
    'Jan 1-15', 'Jan 16-31', 'Feb 1-15', 'Feb 16-28',
    'Mar 1-15', 'Mar 16-31', 'Apr 1-15', 'Apr 16-30'
]

records = []
np.random.seed(42)
for d in districts:
    lon = coords_map.get(d, {}).get('lon', np.nan)
    lat = coords_map.get(d, {}).get('lat', np.nan)
    if pd.isna(lon) or pd.isna(lat):
         continue

    base_val = np.random.uniform(1.2, 2.5)
    for t, window in enumerate(windows):
         progression = base_val * (0.5 + 0.5 * np.sin(np.pi * t / 11))
         val = progression + np.random.normal(0, 0.1)
         records.append({
             'district': d,
             'window': window,
             'longitude': lon,
             'latitude': lat,
             'value': max(0.1, val)
         })

df_spatio = pd.DataFrame(records)

# --- 2. Plot Static Maps Grid as PNG ---
fig, axes = plt.subplots(3, 4, figsize=(18, 12), sharex=True, sharey=True)
axes = axes.flatten()

vmin = df_spatio['value'].min()
vmax = df_spatio['value'].max()

for i, window in enumerate(windows):
    ax = axes[i]
    window_data = df_spatio[df_spatio['window'] == window]

    scatter = ax.scatter(
        window_data['longitude'],
        window_data['latitude'],
        c=window_data['value'],
        cmap='RdYlGn',
        s=150,
        edgecolor='k',
        vmin=vmin,
        vmax=vmax
    )

    ax.set_title(f"Time Window: {window}", fontsize=12, fontweight='bold')
    ax.grid(True, linestyle=':', alpha=0.6)
    if i % 4 == 0:
        ax.set_ylabel('Latitude')
    if i >= 8:
        ax.set_xlabel('Longitude')

# Add a single colorbar for the entire grid
cbar_ax = fig.add_axes([0.92, 0.15, 0.02, 0.7])
fig.colorbar(scatter, cax=cbar_ax, label='Indicator Value')

plt.suptitle('Spatio-Temporal Sequence Maps (Nov - Apr)', fontsize=18, fontweight='bold', y=0.95)

# Save the figure as PNG
output_png = 'spatio_temporal_sequence_maps.png'
plt.savefig(output_png, dpi=300, bbox_inches='tight')
print(f"Successfully exported sequence maps to {output_png}")

# Display inline
plt.show()

