# Handle safe background selection to prevent 403 forbidden API blocks
if map_background == "OpenStreetMap":
    try:
        Map.add_basemap('OpenStreetMap')
    except Exception:
        pass
elif map_background == "Transparent (No Background)":
    Map.clear_layers()

try:
    # Initialize GEE with configured project context
    project_id = globals().get('EE_PROJECT', 'cnn-lstm-crop-yield')
    try:
        ee.Initialize(project=project_id)
    except Exception:
        pass

    # Get GEE vector and raster datasets
    gb_districts = (ee.FeatureCollection('WM/geoLab/geoBoundaries/600/ADM2')
                    .filter(ee.Filter.eq('shapeGroup', 'ZMB')))
    cropland = ee.ImageCollection('ESA/WorldCover/v200').first().select('Map').eq(40).selfMask()

    # Apply layer filtering criteria dynamically
    if cropland_filter == "Show All":
        Map.addLayer(cropland.clip(gb_districts.geometry()), {'palette': ['#f1c40f']}, 'ESA Cropland (Yellow)')
        Map.addLayer(gb_districts.style(color='black', fillColor='00000000', width=1.5), {}, 'Zambia District Boundaries')
    elif cropland_filter == "Show Cropland Only":
        Map.addLayer(cropland.clip(gb_districts.geometry()), {'palette': ['#2ecc71']}, 'Cropland (Green Mask)')
    elif cropland_filter == "Show Districts Only":
        Map.addLayer(gb_districts.style(color='#2c3e50', fillColor='00000000', width=2), {}, 'Zambia Districts')

except Exception as e:
    print(f"Geospatial Layer Load Info: {e}")

globals()['Map'] = Map
display(Map)

